"""Webhook request handling for Linkweave billing events."""

from __future__ import annotations

import json
import os
from collections.abc import Mapping
from typing import Any

from event_store import append_event
from signature_utils import verify_signature


_REQUIRED_STRING_FIELDS = ("event_id", "event_type", "account_id")


def _rejected(reason: str) -> dict[str, Any]:
    return {"status": "rejected", "reason": reason}


def handle_webhook(request: Mapping[str, Any]) -> dict[str, Any]:
    """Validate and enqueue one payment event."""

    if not isinstance(request, Mapping):
        return _rejected("malformed request")

    headers = request.get("headers")
    body = request.get("body")

    if not isinstance(headers, Mapping):
        return _rejected("malformed request")
    if not isinstance(body, (bytes, bytearray)):
        return _rejected("malformed request")

    secret = os.environ.get("WEBHOOK_SECRET", "")

    # This endpoint is publicly reachable (see deployment.json: "ingress":
    # "public"). The legacy relay adapter made the signature header optional
    # because deliveries were pre-authenticated on a trusted internal hop.
    # That compatibility path is unsafe on a public route -- omitting the
    # header would bypass authentication entirely -- so the signature is
    # always required and verified here.
    signature = headers.get("X-Webhook-Signature")
    if not verify_signature(bytes(body), signature, secret):
        return _rejected("invalid signature")

    try:
        event = json.loads(bytes(body).decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return _rejected("invalid JSON")

    if not isinstance(event, dict):
        return _rejected("malformed event")

    for field in _REQUIRED_STRING_FIELDS:
        if not isinstance(event.get(field), str):
            return _rejected("malformed event")

    append_event(event)
    return {"status": "accepted", "event_id": event["event_id"]}

